    })

body_tokens = body_token_estimate(content)
if max_body_tokens is not None and body_tokens is not None and body_tokens > max_body_tokens:
    issues.append({
        "severity": "high",
        "field": "body",
        "message": f"body token estimate {body_tokens} exceeds max {max_body_tokens}",
    })

